    const b = (req.body as Record<string, unknown> | undefined)?.[kunci];
    if (b !== undefined && b !== null && String(b) !== '' && String(b) !== 'semua' && !angkaMurni(b)) kodeMinta.push(String(b).trim());
  }","allowMultiple":false},{"oldString":"  // Id gudang dicek langsung ke daftar id yang diizinkan. 'gudang' = id gudang
