  for (const kunci of ['gudang', 'gudang_id', 'warehouse_id', 'warehouseId', 'gudangId', 'store_id', 'dari_warehouse', 'ke_warehouse', 'dari_gudang', 'ke_gudang']) {
    const q = req.query[kunci];
    if (q !== undefined && q !== '' && q !== 'semua') idMinta.push(Number(q));
    const b = (req.body as Record<string, unknown> | undefined)?.[kunci];
