{"kind":"tool","id":"hfZg76aNJkg","toolName":"write_file","input":{"path":".freebuff/verif-gudang-impor.ts","content":"/** Verifikasi sementara: kolom gudang + stok_awal pada impor Produk. */\nimport ExcelJS from 'exceljs';\nimport { DatabaseSync } from 'node:sqlite';\nimport { headerUji } from '../scripts/sesi-uji.mjs';\n\nconst BASE = process.env.BASE ?? 'http://127.0.0.1:3001';\nconst db = new DatabaseSync('data/app.db');\nlet gagal = 0;\nconst cek = (nama: string, ok: boolean, info = '') => {\n  console.log(`${ok ? '✔' : '✘'} ${nama}${info ? ` — ${info}` : ''}`);\n  if (!ok) gagal++;\n};\n\nasync function req(method: string, url: string, body?: unknown): Promise<{ status: number; data: any }> {\n  const res = await fetch(`${BASE}${url}`, {\n    method,\n    headers: await headerUji(),\n    body: body === undefined ? undefined : JSON.stringify(body),\n  });\n  let data: any = null;\n  try { data = await res.json(); } catch { /* non-JSON */ }\n  return { status: res.status, data };\n}\n\nasync function wb64(kolom: string[], baris: (string | number)[][]): Promise<string> {\n  const wb = new ExcelJS.Workbook();\n  const ws = wb.addWorksheet('Data');\n  ws.addRow(kolom);\n  for (const b of baris) ws.addRow(b);\n  return Buffer.from(await wb.xlsx.writeBuffer() as ArrayBuffer).toString('base64');\n}\n\nconst bersih = () => {\n  db.exec(`\n    DELETE FROM stock_ledger WHERE product_id IN (SELECT id FROM products WHERE kode_item LIKE 'UJIG-%');\n    DELETE FROM stock_balances WHERE product_id IN (SELECT id FROM products WHERE kode_item LIKE 'UJIG-%');\n    DELETE FROM import_errors WHERE batch_id IN (SELECT id FROM import_batches WHERE nama_file LIKE 'ujig%');\n    DELETE FROM import_batches WHERE nama_file LIKE 'ujig%';\n    DELETE FROM products WHERE kode_item LIKE 'UJIG-%';\n  `);\n};\n\n// 1) Template memuat kolom gudang + stok_awal\nconst tres = await fetch(`${BASE}/api/master/produk/template`, { headers: await headerUji() });\nconst tbuf = Buffer.from(await tres.arrayBuffer());\nconst twb = new ExcelJS.Workbook();\nawait twb.xlsx.load(tbuf as any);\nconst data = twb.getWorksheet('Data')!;\nconst judul: string[] = [];\n(data.getRow(1) as any).eachCell((c: any) => judul.push(String(c.value)));\ncek('template memuat kolom gudang', judul.includes('gudang'), judul.join(','));\ncek('template memuat kolom stok_awal', judul.includes('stok_awal'));\n\n// 2) Gudang rujukan\nconst g = await req('GET', '/api/master/gudang?per=5');\nconst daftar: any[] = g.data?.data ?? [];\ncek('ada gudang aktif di master', daftar.length > 0, JSON.stringify(daftar.map((x) => x.kode)));\nconst KODE_GUDANG = String(daftar[0]?.kode ?? '');\nconst GUDANG_ID = Number(daftar[0]?.id ?? 0);\n\n// 3) Pra-tinjau: kolom Gudang + Stok Awal terbaca\nconst KOLOM = ['kode_item', 'nama_produk', 'sku', 'Gudang', 'Stok Awal'];\nconst BARIS: (string | number)[][] = [['UJIG-9001', 'Produk Uji Gudang', 'UJIGSKU-1', KODE_GUDANG, 10]];\nconst b64 = await wb64(KOLOM, BARIS);\nconst pemetaan = { kode_item: 'kode_item', nama_produk: 'nama_produk', sku: 'sku', gudang: 'Gudang', stok_awal: 'Stok Awal' };\nconst pra = await req('POST', '/api/master/produk/impor/pra-tinjau', {\n  nama_file: 'ujig-valid.xlsx', data_base64: b64, pemetaan, opsi: { perbarui: true, lewati_error: true, buat_otomatis: true },\n});\ncek('pra-tinjau valid 1 baris', pra.data?.baris_valid === 1, JSON.stringify(pra.data?.baris));\ncek('pra-tinjau echo gudang', pra.data?.baris?.[0]?.gudang === KODE_GUDANG, JSON.stringify(pra.data?.baris?.[0]));\ncek('pra-tinjau echo stok_awal', pra.data?.baris?.[0]?.stok_awal === 10, JSON.stringify(pra.data?.baris?.[0]));\n\n// 4) Konfirmasi: produk + saldo + kartu stok terbentuk\nconst konf = await req('POST', '/api/master/produk/impor', {\n  nama_file: 'ujig-valid.xlsx', data_base64: b64, pemetaan, opsi: { perbarui: true, lewati_error: true, buat_otomatis: true },\n});\ncek('konfirmasi 1 baru', konf.data?.jumlah_baru === 1, JSON.stringify({ baru: konf.data?.jumlah_baru, error: konf.data?.baris_error }));\nconst prod = db.prepare(`SELECT id FROM products WHERE kode_item = 'UJIG-9001'`).get() as any;\nconst saldo = db.prepare(`SELECT qty FROM stock_balances WHERE product_id = ? AND warehouse_id = ?`).get(prod?.id, GUDANG_ID) as any;\ncek('saldo gudang = 10', Number(saldo?.qty) === 10, `qty=${saldo?.qty}`);\nconst kartu = db.prepare(`SELECT COUNT(*) AS n FROM stock_ledger WHERE product_id = ? AND warehouse_id = ? AND tipe_dokumen = 'penyesuaian'`).get(prod?.id, GUDANG_ID) as any;\ncek('kartu stok penyesuaian ada', Number(kartu?.n) >= 1, `n=${kartu?.n}`);\n\n// 5) Impor ulang: tidak menumpuk (peringatan, saldo tetap)\nconst pra2 = await req('POST', '/api/master/produk/impor/pra-tinjau', {\n  nama_file: 'ujig-ulang.xlsx', data_base64: b64, pemetaan, opsi: { perbarui: true, lewati_error: true, buat_otomatis: true },\n});\nconst adaIngat = (pra2.data?.peringatan ?? []).some((p: any) => String(p.kolom ?? '').includes('stok_awal'));\ncek('impor ulang memberi peringatan stok_awal', adaIngat, JSON.stringify(pra2.data?.peringatan));\n\n// 6) Negatif: gudang tak dikenal\nconst b64Buruk = await wb64(KOLOM, [['UJIG-9002', 'Produk Gudang Buruk', 'UJIGSKU-2', 'GUDANG-TAK-ADA', 5]]);\nconst praBuruk = await req('POST', '/api/master/produk/impor/pra-tinjau', {\n  nama_file: 'ujig-buruk.xlsx', data_base64: b64Buruk,\n  pemetaan, opsi: { perbarui: true, lewati_error: true, buat_otomatis: true },\n});\ncek('gudang tak dikenal → error', (praBuruk.data?.baris_error ?? 0) >= 1, JSON.stringify(praBuruk.data?.errors?.[0] ?? praBuruk.data?.ringkasan));\n\n// 7) Negatif: stok_awal tanpa gudang\nconst b64Tanpa = await wb64(KOLOM, [['UJIG-9003', 'Produk Tanpa Gudang', 'UJIGSKU-3', '', 7]]);\nconst praTanpa = await req('POST', '/api/master/produk/impor/pra-tinjau', {\n  nama_file: 'ujig-tanpa.xlsx', data_base64: b64Tanpa,\n  pemetaan, opsi: { perbarui: true, lewati_error: true, buat_otomatis: true },\n});\ncek('stok_awal tanpa gudang → error', (praTanpa.data?.baris_error ?? 0) >= 1, JSON.stringify(praTanpa.data?.errors?.[0] ?? praTanpa.data?.ringkasan));\n\n// 8) Urungkan: produk + saldo + kartu kembali bersih\nconst batchId = konf.data?.batch_id;\nconst und = await req('POST', '/api/master/produk/impor/urungkan', { batch_id: batchId });\ncek('urungkan ok', und.status === 200, JSON.stringify(und.data));\nconst sisaProd = db.prepare(`SELECT COUNT(*) AS n FROM products WHERE kode_item = 'UJIG-9001'`).get() as any;\nconst sisaSaldo = db.prepare(`SELECT COUNT(*) AS n FROM stock_balances WHERE product_id = ?`).get(prod?.id) as any;\nconst sisaKartu = db.prepare(`SELECT COUNT(*) AS n FROM stock_ledger WHERE product_id = ?`).get(prod?.id) as any;\ncek('produk terhapus saat diurungkan', Number(sisaProd?.n) === 0);\ncek('saldo ikut terhapus', Number(sisaSaldo?.n) === 0, `n=${sisaSaldo?.n}`);\ncek('kartu ikut terhapus', Number(sisaKartu?.n) === 0, `n=${sisaKartu?.n}`);\n\nbersih();\nconsole.log(gagal === 0 ? 'SEMUA LULUS' : `${gagal} GAGAL`);\nprocess.exit(gagal === 0 ? 0 : 1);\n"}}


