e-gap-bottom) * var(--jarak-skala))\n    calc(var(--page-gap-left) * var(--jarak-skala));\n  box-sizing: border-box;\n  /* U3 — kolom flex supaya kartu daftar boleh MENGISI sisa tinggi layar\n     (tabel menggulir di dalam, bukan seluruh halaman). */\n  display: flex;\n  flex-direction: column;\n}","allowMultiple":false},{"oldString":"/* U2 — padding kartu 16-20px (menyesuaikan mode kepadatan). */\n.kartu {\n  background: var(--panel);\n  border: 1px solid var(--border);\n  border-radius: var(--radius);\n  box-shadow: var(--bayangan);\n  padding: var(--padding-kartu);\n}","newString":"/* AT1 — PageCard: padding 24px vertikal / 34px horizontal, radius 16px.\n   Kepadatan hanya mengalikan jarak via --jarak-skala. */\n.kartu {\n  background: var(--panel);\n  border: 1px solid var(--border);\n  border-radius: var(--card-radius);\n  box-shadow: var(--bayangan);\n  padding: var(--padding-kartu);\n}","allowMultiple":false}]}}


