### CONTOH LOGIKA JAVASCRIPT & KEYBOARD EVENT HANDLER:

```javascript
// 1. Filter Autocomplete berdasarkan Gudang
function searchProductAutocomplete(query) {
  const selectedWarehouseId = document.getElementById('select-gudang').value;

  if (!selectedWarehouseId) {
    alert("Silakan pilih gudang terlebih dahulu.");
    return [];
  }

  // Filter produk yang ada di gudang terpilih
  return allProducts.filter(product => {
    const isProductInWarehouse = product.stocks && product.stocks[selectedWarehouseId] !== undefined;
    const matchesQuery = product.name.toLowerCase().includes(query.toLowerCase()) || 
                         product.code.toLowerCase().includes(query.toLowerCase()) ||
                         product.barcode === query;

    return isProductInWarehouse && matchesQuery;
  });
}

// 2. Add Item & Retain Focus on Search Input
function onSelectProductFromAutocomplete(product) {
  addItemToTable(product);

  // Clear search input & kembalikan fokus ke pencarian
  const searchInput = document.getElementById('search-item-input');
  searchInput.value = '';
  searchInput.focus();
}

// 3. Full Keyboard Navigation Handler
document.getElementById('search-item-input').addEventListener('keydown', function(e) {
  // Pindah ke tabel saat tekan Tab atau ArrowDown pada input kosong
  if ((e.key === 'ArrowDown' || e.key === 'Tab') && this.value === '') {
    e.preventDefault();
    const firstQtyInput = document.querySelector('.table-qty-input[data-row="0"]');
    if (firstQtyInput) firstQtyInput.focus();
  }
});

// 4. Navigasi Up/Down di dalam Tabel Item
document.addEventListener('keydown', function(e) {
  const activeElement = document.activeElement;

  if (activeElement && activeElement.classList.contains('table-qty-input')) {
    const currentRow = parseInt(activeElement.getAttribute('data-row'), 10);

    if (e.key === 'ArrowDown') {
      e.preventDefault();
      const nextInput = document.querySelector(`.table-qty-input[data-row="${currentRow + 1}"]`);
      if (nextInput) nextInput.focus();
    } 
    else if (e.key === 'ArrowUp') {
      e.preventDefault();
      if (currentRow === 0) {
        // Baris teratas -> kembalikan ke kolom pencarian
        document.getElementById('search-item-input').focus();
      } else {
        const prevInput = document.querySelector(`.table-qty-input[data-row="${currentRow - 1}"]`);
        if (prevInput) prevInput.focus();
      }
    }
  }
});

