.transaksi-grid {
  display: block;
}
.transaksi-utama {
  display: contents;
}
@media (min-width: 768px) {
  .transaksi-grid {
    display: grid;
    grid-template-columns: minmax(0, 8fr) minmax(0, 4fr);
    gap: 1.25rem;
    align-items: start;
  }
  .transaksi-utama {
    display: flex;
    flex-direction: column;
    min-width: 0;
  }
  .transaksi-grid > .transaksi-aksi {
    grid-column: 1;
  }
  .transaksi-ringkas {
    position: sticky;
    top: 0.75rem;
    min-width: 0;
  }
  .transaksi-ringkas .ringkas-beli {
    width: 100%;
    margin: 0;
  }
}
@media (min-width: 1280px) {
  .transaksi-grid {
    grid-template-columns: minmax(0, 9fr) minmax(0, 3fr);
  }
}

