// Controller Handler untuk Fetch Produk Terisolasi
async function getProducts(req, res) {
  try {
    const user = req.user; // User session data
    const requestedWarehouse = req.query.warehouse_id;

    // Ambil daftar ID gudang yang diizinkan untuk user ini, misal: ['GD-2']
    const allowedWarehouses = user.allowed_warehouses || [];

    if (allowedWarehouses.length === 0 && user.role !== 'owner') {
      return res.status(403).json({ success: false, message: "User tidak memiliki akses ke gudang manapun." });
    }

    let warehouseFilterSQL = "";
    let queryParams = [];

    // Logika Filtering Ketat:
    if (user.role === 'owner' && requestedWarehouse && requestedWarehouse !== 'all') {
      warehouseFilterSQL = "WHERE p.warehouse_id = ?";
      queryParams.push(requestedWarehouse);
    } else if (user.role !== 'owner') {
      if (requestedWarehouse && requestedWarehouse !== 'all') {
        // Cek jika gudang yang diminta tidak diizinkan
        if (!allowedWarehouses.includes(requestedWarehouse)) {
          return res.status(403).json({ success: false, message: "Akses gudang ditolak." });
        }
        warehouseFilterSQL = "WHERE p.warehouse_id = ?";
        queryParams.push(requestedWarehouse);
      } else {
        // Jika memilih "Semua gudang", batasi HANYA pada gudang yang diizinkan
        const placeholders = allowedWarehouses.map(() => '?').join(',');
        warehouseFilterSQL = `WHERE p.warehouse_id IN (${placeholders})`;
        queryParams.push(...allowedWarehouses);
      }
    }

    // Eksekusi Query Produk yang Terisolasi
    const query = `
      SELECT p.*, s.qty, w.name as warehouse_name 
      FROM products p
      LEFT JOIN stocks s ON p.id = s.product_id
      LEFT JOIN warehouses w ON p.warehouse_id = w.id
      ${warehouseFilterSQL}
      ORDER BY p.id DESC
    `;

    const products = await db.all(query, queryParams);
    return res.json({ success: true, data: products });

  } catch (error) {
    return res.status(500).json({ success: false, message: error.message });
  }
}

