 * (tidak ada baris). Dipakai daftar produk, riwayat pembelian/penjualan,
 * autocomplete, dan widget dasbor agar "Semua" tidak berarti "semua sistem".
 */
export function syaratGudangSesi(req: Request, kolom: string): { sql: string; params: number[] } {
  const k = req.konteks;
  if (!k || k.admin) return { sql: '', params: [] };
  const cakupan = k.cakupanToko;
  if (cakupan === null || cakupan === undefined) return { sql: '', params: [] };
  if (cakupan.length === 0) return { sql: '1 = 0', params: [] };
  const ids = [...idGudangDiizinkan(cakupan)];
  if (ids.length === 0) return { sql: '1 = 0', params: [] };
  return { sql: `${kolom} IN (${ids.map(() => '?').join(',')})`, params: ids };
}

