// isolasi gudang (produk eksklusif GD-B tidak muncul di grid GD-A). HAPUS setelah uji.
import { DatabaseSync } from 'node:sqlite';

const db = new DatabaseSync('data/uji-posfoto.db', { readOnly: true });

const gudang = db.prepare('SELECT id, kode, nama FROM warehouses ORDER BY id').all() as { id: number; kode: string; nama: string }[];
console.log('GUDANG:', JSON.stringify(gudang));
if (gudang.length < 2) {
  console.log('SKIP: butuh >= 2 gudang untuk uji silang.');
  process.exit(0);
}

const grid = (gid: number) =>
  db.prepare(
    `SELECT p.id, p.nama,
            COALESCE((SELECT SUM(sb.qty) FROM stock_balances sb WHERE sb.product_id = p.id AND sb.warehouse_id IN (?)), 0) AS stok
     FROM products p
     WHERE p.deleted_at IS NULL AND p.aktif = 1
       AND EXISTS (SELECT 1 FROM stock_balances sbG WHERE sbG.product_id = p.id AND sbG.warehouse_id = ?)
     ORDER BY p.nama ASC LIMIT 500`,
  ).all(gid, gid) as { id: number; nama: string; stok: number }[];

const [A, B] = [gudang[0].id, gudang[1].id];
const gA = grid(A);
const gB = grid(B);
const setA = new Set(gA.map((p) => p.id));
const setB = new Set(gB.map((p) => p.id));

// Produk yang HANYA punya saldo di B (tidak ada baris balance di A).
const eksklusifB = db.prepare(
  `SELECT product_id FROM stock_balances WHERE warehouse_id = ?
   EXCEPT SELECT product_id FROM stock_balances WHERE warehouse_id = ?`,
).all(B, A) as { product_id: number }[];
const bocor = eksklusifB.filter((r) => setA.has(r.product_id));

console.log(`grid GD-${A}: ${gA.length} produk | grid GD-${B}: ${gB.length} produk`);
console.log(`produk eksklusif GD-${B}: ${eksklusifB.length} | bocor ke grid GD-${A}: ${bocor.length}`);
if (bocor.length > 0) {
  console.log('CONTOH BOCOR:', JSON.stringify(bocor.slice(0, 5)));
  process.exit(1);
}
// Kategori grid A hanya dari produk grid A (prinsip chip terkunci).
const kat = db.prepare(
  `SELECT DISTINCT p.category_id FROM products p WHERE p.id IN (${[...setA].map(() => '?').join(',') || 'NULL'}) AND p.category_id IS NOT NULL`,
).all(...[...setA]) as { category_id: number }[];
console.log(`kategori unik di grid GD-${A}: ${kat.length} (berasal hanya dari produk grid A)`);
console.log('LOLOS: grid terkunci per gudang, tidak ada kebocoran silang.');
"}}


