    asyncHandler((req, res) => {
      const body = (req.body ?? {}) as Record<string, unknown>;
      const barcode = String(body.barcode ?? '').trim();
      if (!barcode) throw tolak(400, 'Barcode kosong — pindai atau ketik barcode dulu.');
