        : null;
      const terdaftarDi = (productId: number): boolean =>
        !gudangId ||
        !!get<{ product_id: number }>('SELECT product_id FROM stock_balances WHERE product_id = ? AND warehouse_id = ?', productId, gudangId);

      // 1) Paket/Box lebih dulu (barcode_box).
      const pack = get<{ id: number; kode_box: string; nama: string; barcode_box: string }>(
