+/* ==========================================================================
+   POS Deep Teal Edition — dark high-density theme (tanpa Tailwind).
+   Scope: hanya di dalam .pos-shell agar modul lain tidak ikut berubah.
+   Logika bisnis / isolasi gudang tidak disentuh — murni visual.
+   Palet: bg #0b0f19 (slate-950), panel #0f172a/#111c33 (slate-900),
+   border #1e293b (slate-800), aksen teal #14b8a6 / #0d9488.
+   Angka & kode: ui-monospace / JetBrains Mono fallback.
+   ========================================================================== */
+
+.pos-shell {
+  --teal-50: #f0fdfa;
+  --teal-100: #ccfbf1;
+  --teal-400: #2dd4bf;
+  --teal-500: #14b8a6;
+  --teal-600: #0d9488;
+  --teal-700: #0f766e;
+  --teal-900: #134e4a;
+  --slate-950: #0b0f19;
+  --slate-900: #0f172a;
+  --slate-850: #151f32;
+  --slate-800: #1e293b;
+  --slate-700: #334155;
+  --slate-400: #94a3b8;
+  --slate-300: #cbd5e1;
+  --slate-200: #e2e8f0;
+  --mono: "JetBrains Mono", ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
+  background: var(--slate-950);
+  color: var(--slate-200);
+  font-family: Inter, system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
+}
+
+/* --- Top bar: padat, 1 baris, gelap --- */
+.pos-shell .pos-kepala {
+  background: var(--slate-900);
+  border-bottom: 1px solid var(--slate-800);
+  color: var(--slate-200);
+  padding: 0.375rem 0.75rem;
+  min-height: 3rem;
+  gap: 0.75rem;
+}
+.pos-shell .pos-kepala__judul {
+  font-weight: 800;
+  letter-spacing: 0.04em;
+  text-transform: uppercase;
+  font-size: 0.8125rem;
+  color: var(--teal-400);
+}
+.pos-shell .pos-jejak { color: var(--teal-400); }
+.pos-shell .pos-pemisah { color: var(--slate-700); }
+.pos-shell .pos-toko { color: var(--slate-400); font-weight: 500; text-transform: none; }
+.pos-shell .pos-kepala__tengah { gap: 0.5rem; }
+.pos-shell .pos-shift {
+  background: var(--slate-850);
+  border: 1px solid var(--slate-800);
+  border-radius: 0.5rem;
+  font-size: 0.75rem;
+  color: var(--slate-300);
+}
+.pos-shell .pos-shift b { color: var(--teal-400); font-family: var(--mono); }
+.pos-shell .pos-kepala__kanan .tombol,
+.pos-shell .pos-tombol-keluar {
+  background: var(--slate-800);
+  border: 1px solid var(--slate-700);
+  color: var(--slate-200);
+  border-radius: 0.5rem;
+  font-size: 0.75rem;
+  white-space: nowrap;
+}
+.pos-shell .pos-kepala__kanan .tombol:hover,
+.pos-shell .pos-tombol-keluar:hover {
+  background: var(--teal-600);
+  border-color: var(--teal-600);
+  color: #fff;
+}
+.pos-shell .pos-datetime {
+  background: var(--slate-950);
+  border: 1px solid var(--slate-800);
+  color: var(--slate-200);
+  border-radius: 0.5rem;
+  font-family: var(--mono);
+  font-size: 0.75rem;
+}
+.pos-shell .pos-datetime svg { color: var(--teal-400); }
+.pos-shell .pos-fullscreen-btn {
+  background: var(--slate-800);
+  border: 1px solid var(--slate-700);
+  color: var(--slate-300);
+  border-radius: 0.5rem;
+  padding: 0.375rem 0.625rem;
+  cursor: pointer;
+  font: inherit;
+  font-size: 0.75rem;
+  white-space: nowrap;
+}
+.pos-shell .pos-fullscreen-btn:hover {
+  background: var(--slate-700);
+  color: #fff;
+}
+
+/* --- Badan 2 kolom: kiri 65% katalog, kanan 360–420px cart --- */
+.pos-shell .pos-badan {
+  background: var(--slate-950);
+  gap: 0;
+}
+.pos-shell .pos-kiri {
+  flex: 1 1 65%;
+  min-width: 0;
+  background: var(--slate-900);
+  border-right: 1px solid var(--slate-800);
+}
+.pos-shell .pos-kanan {
+  width: clamp(22.5rem, 35%, 26.25rem);
+  flex: none;
+  background: var(--slate-900);
+  border-left: 1px solid var(--slate-800);
+}
+
+/* --- Kontrol atas kiri: search + switcher mode + pills --- */
+.pos-shell .pos-filter {
+  background: var(--slate-900);
+  border-bottom: 1px solid var(--slate-800);
+  padding: 0.625rem;
+  gap: 0.5rem;
+}
+.pos-shell .pos-cari input {
+  background: var(--slate-950);
+  border: 1px solid var(--slate-700);
+  color: #f1f5f9;
+  border-radius: 0.5rem;
+  font-family: var(--mono);
+  letter-spacing: 0.01em;
+}
+.pos-shell .pos-cari input::placeholder { color: var(--slate-400); }
+.pos-shell .pos-cari input:focus {
+  border-color: var(--teal-500);
+  box-shadow: 0 0 0 1px var(--teal-500);
+  outline: none;
+}
+.pos-shell .pos-cari__ikon { color: var(--teal-400); }
+.pos-shell .pos-kbd {
+  background: var(--slate-800);
+  border: 1px solid var(--slate-700);
