   POS — Soft Earthy / Sage Minimalist (senada Dashboard "RuangRapi").
   --------------------------------------------------------------------------
   Murni visual: hanya warna, border, radius, spacing, tipografi. Tidak ada
   logika, ID/class selector, shortcut, maupun struktur fitur yang diubah.
   Dimuat SETELAH pos-deep-teal.css sehingga menimpa tema gelap HANYA pada
   mode siang (html TANPA data-theme="dark"). Mode malam tetap Deep Teal.
   ========================================================================== */

/* Tipografi modern (kedua tema, visual saja). */
.pos-shell {
  font-family: 'Aptos', 'Segoe UI', system-ui, -apple-system, sans-serif;
}

/* --- Token earthy untuk mode siang (dipetakan ke hook --slate/--teal lama) - */
:root:not([data-theme="dark"]) .pos-shell {
  --teal-50: #e5f2e9;
  --teal-100: #e5f2e9;
  --teal-400: #1e6247;
  --teal-500: #267454;
  --teal-600: #267454;
  --teal-700: #1f6045;
  --teal-900: #1e6247;
  --slate-950: #f4f3ec;
  --slate-900: #ffffff;
  --slate-850: #f8f8f4;
  --slate-800: #e9ece5;
  --slate-700: #dfe4dc;
  --slate-400: #768078;
  --slate-300: #4b5550;
  --slate-200: #202a24;
}

/* --- Panel pencarian: kartu putih radius 16px --- */
:root:not([data-theme="dark"]) .pos-shell .pos-filter {
  background: #ffffff;
  border: 1px solid #e9ece5;
  border-radius: 16px;
  padding: 0.625rem 0.75rem;
}

/* --- Panel keranjang: kartu putih radius 16px (desktop saja; laci ponsel
       <1024px tidak disentuh agar mekanisme drawer utuh) --- */
@media (min-width: 1025px) {
  :root:not([data-theme="dark"]) .pos-shell .pos-badan {
    padding: 0.75rem;
    gap: 0.75rem;
  }
  :root:not([data-theme="dark"]) .pos-shell .pos-kanan {
    border: 1px solid #e9ece5;
    border-radius: 16px;
    overflow: hidden;
  }
}

/* --- Tombol utama: toska pekat, teks putih bold, radius 12px --- */
:root:not([data-theme="dark"]) .pos-shell .pos-bayar,
:root:not([data-theme="dark"]) .pos-shell .pos-aksi-bayar {
  background: linear-gradient(135deg, #1f5e43, #267454);
  border-radius: 12px;
  color: #ffffff;
  font-weight: 700;
  box-shadow: 0 6px 16px rgb(38 116 84 / 0.28);
}
:root:not([data-theme="dark"]) .pos-shell .pos-mode-switch {
  border-radius: 12px;
}
:root:not([data-theme="dark"]) .pos-shell .pos-mode-switch button.aktif {
  border-radius: 10px;
  color: #ffffff;
  font-weight: 700;
}

/* --- Tombol sekunder: putih + border halus; hover → border & teks teal --- */
:root:not([data-theme="dark"]) .pos-shell .pos-kepala__kanan .tombol,
:root:not([data-theme="dark"]) .pos-shell .pos-tombol-keluar,
:root:not([data-theme="dark"]) .pos-shell .pos-fullscreen-btn,
:root:not([data-theme="dark"]) .pos-shell .pos-chip,
:root:not([data-theme="dark"]) .pos-shell .pos-fastcash button,
:root:not([data-theme="dark"]) .pos-shell .pos-bayar-cepat button,
:root:not([data-theme="dark"]) .pos-shell .pos-tabel-tambah,
:root:not([data-theme="dark"]) .pos-shell .pos-tombol-lebih,
:root:not([data-theme="dark"]) .pos-shell .pos-baris__kontrol button,
:root:not([data-theme="dark"]) .pos-shell .pos-rincian-btn {
  background: #ffffff;
  border: 1px solid #e9ece5;
  color: #202a24;
}
:root:not([data-theme="dark"]) .pos-shell .pos-kepala__kanan .tombol:hover,
:root:not([data-theme="dark"]) .pos-shell .pos-tombol-keluar:hover,
:root:not([data-theme="dark"]) .pos-shell .pos-fullscreen-btn:hover,
:root:not([data-theme="dark"]) .pos-shell .pos-chip:hover,
:root:not([data-theme="dark"]) .pos-shell .pos-fastcash button:hover,
:root:not([data-theme="dark"]) .pos-shell .pos-bayar-cepat button:hover,
:root:not([data-theme="dark"]) .pos-shell .pos-tabel-tambah:hover,
:root:not([data-theme="dark"]) .pos-shell .pos-tombol-lebih:hover,
:root:not([data-theme="dark"]) .pos-shell .pos-baris__kontrol button:hover,
:root:not([data-theme="dark"]) .pos-shell .pos-rincian-btn:hover,
:root:not([data-theme="dark"]) .pos-shell .pos-kategori button:not(.aktif):hover {
  background: #ffffff;
  border-color: #267454;
  color: #267454;
}

/* --- Input pencarian: radius 12px, fokus ring teal transparan --- */
:root:not([data-theme="dark"]) .pos-shell .pos-cari input {
  border-radius: 12px;
}
:root:not([data-theme="dark"]) .pos-shell .pos-cari input:focus {
  border-color: #267454;
  box-shadow: 0 0 0 3px rgb(38 116 84 / 0.15);
}

/* --- Filter pil lembut + badge netral --- */
:root:not([data-theme="dark"]) .pos-shell .pos-kategori button {
  border-radius: 20px;
}
:root:not([data-theme="dark"]) .pos-shell .pos-kategori button.aktif {
  background: #e5f2e9;
  border-color: #e5f2e9;
  color: #267454;
  font-weight: 700;
}
:root:not([data-theme="dark"]) .pos-shell .pos-shift,
:root:not([data-theme="dark"]) .pos-shell .pos-datetime {
  background: #ffffff;
  border: 1px solid #e9ece5;
}

/* --- Total checkout mencolok: 24px, bobot 800, hijau tua --- */
:root:not([data-theme="dark"]) .pos-shell .pos-total b {
  font-size: 1.375rem;
  font-weight: 800;
  color: #1e6247;
}
:root:not([data-theme="dark"]) .pos-shell .pos-grandtotal__nilai {
  font-size: 1.5rem;
  font-weight: 800;
  color: #1e6247;
}
:root:not([data-theme="dark"]) .pos-shell .pos-grandtotal {
  border-color: #cfe6d7;
}

/* --- Sentuhan kartu katalog di siang hari --- */
:root:not([data-theme="dark"]) .pos-shell .pos-kartu:hover {
  border-color: #9ccbb0;
}
:root:not([data-theme="dark"]) .pos-shell .pos-tabel-cepat tbody tr:hover {
  background: #f7f8f3;
}
