  const r = await fetch(BASE + url, { method: m, headers: H, body: body ? JSON.stringify(body) : undefined });
  const t = await r.text();
  let d; try { d = JSON.parse(t); } catch { d = t; }
  return { ok: r.ok, status: r.status, data: d };
};

const gudang = (await api('GET', '/api/master/gudang?per=1')).data;
const gid = gudang.data?.[0]?.id ?? gudang[0]?.id;
const sup = await api('GET', '/api/master/pemasok?per=1');
const supId = sup.data.data?.[0]?.id ?? sup.data[0]?.id;
const prod = await api('GET', `/api/pos/produk?gudang=${gid}`);
const p = prod.data.data?.[0] ?? prod.data[0];
console.log('gudang:', gid, 'pemasok:', supId, 'produk:', p?.id, p?.sku);

// Buat draft pembelian manual berisi 1 item Rp 0
const draft = await api('POST', '/api/pembelian', {
  warehouse_id: gid, supplier_id: supId, tanggal: new Date().toISOString().slice(0, 10),
  items: [{ product_id: p.id, qty: 10, unit_id: null, harga_beli: 0, diskon: 0 }],
});
console.log('buat draft:', draft.status, JSON.stringify(draft.data).slice(0, 300));
const id = draft.data?.data?.id ?? draft.data?.id;
if (!id) process.exit(0);

const t0 = Date.now();
const terima = await api('POST', `/api/pembelian/${id}/terima`, {});
console.log(`terima (${Date.now() - t0}ms):`, terima.status, JSON.stringify(terima.data).slice(0, 300));

const s0 = Date.now();
const sahkan = await api('POST', `/api/pembelian/${id}/sahkan`, {});
console.log(`sahkan (${Date.now() - s0}ms):`, sahkan.status, JSON.stringify(sahkan.data).slice(0, 300));
