{"kind":"tool","id":"jPKtTdoqLZs","toolName":"write_file","input":{"path":"/tmp/uji-grn-kasir2.mjs","content":"const BASE = 'http://127.0.0.1:3029';
async function masuk(username, sandi) {
  const r = await fetch(`${BASE}/api/auth/masuk`, {
    method: 'POST', headers: { 'content-type': 'application/json' },
    body: JSON.stringify({ username, sandi }),
  });
  if (!r.ok) throw new Error(`login ${username} gagal: ` + await r.text());
  return `ns_sesi=${/ns_sesi=([^;]+)/.exec(r.headers.get('set-cookie'))[1]}`;
}
const ckAdmin = await masuk('admin', 'uji12345');
const ckKasir = await masuk('KasirTG', 'uji12345');
const H = (ck, peran) => ({ 'content-type': 'application/json', cookie: ck, 'x-peran': peran });
const api = async (ck, peran, m, url, body) => {
  const r = await fetch(BASE + url, { method: m, headers: H(ck, peran), body: body ? JSON.stringify(body) : undefined });
  const t = await r.text();
  let d; try { d = JSON.parse(t); } catch { d = t; }
  return { ok: r.ok, status: r.status, data: d };
};
// Draft baru sebagai admin di GD-2 (id 76), item Rp 0
const draft = await api(ckAdmin, 'admin', 'POST', '/api/pembelian', {
  warehouse_id: 76, supplier_id: 68, tanggal: new Date().toISOString().slice(0, 10),
  items: [{ product_id: 1996, qty: 10, unit_id: null, harga_beli: 0, diskon: 0 }],
});
const id = draft.data?.data?.id ?? draft.data?.id;
console.log('draft id:', id, 'status:', draft.status);
// Terima sebagai KasirTG (tanpa izin sahkan)
const terima = await api(ckKasir, 'kasir', 'POST', `/api/pembelian/${id}/terima`, {});
console.log('terima sbg kasir:', terima.status, JSON.stringify(terima.data));
// Simulasi filter toast frontend
const POLA = /tidak punya akses|tidak memiliki izin|tidak berhak/i;
const pesan = terima.data?.pesan ?? '';
console.log('toast ditampilkan?', !POLA.test(pesan), '| pesan:', pesan);
"}}


