  scrollToLatestCartItem(container);
}

// Function Auto-Scroll
function scrollToLatestCartItem(container) {
  // Opsi 1: Direct Scroll Top ke Paling Bawah
  container.scrollTop = container.scrollHeight;

  // Opsi 2: Smooth ScrollIntoView pada Item Terakhir
  const lastItemElement = container.lastElementChild;
  if (lastItemElement) {
    lastItemElement.scrollIntoView({ behavior: 'smooth', block: 'end' });
  }
}

