// Function untuk memastikan gudang memiliki minimal 1 lokasi aktif (Auto-Fallback)
async function ensureWarehouseLocation(trx, warehouseId) {
  // 1. Cek apakah gudang sudah memiliki lokasi
  let location = await trx.get(
    'SELECT id FROM warehouse_locations WHERE warehouse_id = ? ORDER BY is_default DESC LIMIT 1',
    [warehouseId]
  );

  // 2. Jika belum ada lokasi, buatkan lokasi default secara otomatis
  if (!location) {
    const defaultLocationId = `LOC-${warehouseId}-DEFAULT`;
    await trx.run(
      `INSERT INTO warehouse_locations (id, warehouse_id, name, is_default, created_at) 
       VALUES (?, ?, 'Utama', 1, ?)`,
      [defaultLocationId, warehouseId, new Date().toISOString()]
    );
    return defaultLocationId;
  }

  return location.id;
}

// Handler Pengesahan Faktur Pembelian (Approve Purchase Invoice)
async function approvePurchaseInvoiceHandler(req, res) {
  const purchaseId = req.params.id;

  try {
    const purchase = await db.get('SELECT * FROM purchases WHERE id = ?', [purchaseId]);
    if (!purchase) {
      return res.status(404).json({ success: false, message: 'Dokumen pembelian tidak ditemukan.' });
    }

    const items = await db.all('SELECT * FROM purchase_items WHERE purchase_id = ?', [purchaseId]);

    await db.transaction(async (trx) => {
      // Get atau Auto-create lokasi default untuk gudang transaksi
      const validLocationId = await ensureWarehouseLocation(trx, purchase.warehouse_id);

      // Mutasi Stok untuk Setiap Item menggunakan Valid Location
      for (const item of items) {
        await trx.run(
          `INSERT INTO stock_cards (product_id, warehouse_id, location_id, qty_in, reference_no, created_at)
           VALUES (?, ?, ?, ?, ?, ?)`,
          [item.product_id, purchase.warehouse_id, validLocationId, item.qty, purchase.ref_no, new Date().toISOString()]
        );

        // Update Saldo Stok Produk per Gudang
        await trx.run(
          `UPDATE stocks SET qty = qty + ? WHERE product_id = ? AND warehouse_id = ?`,
          [item.qty, item.product_id, purchase.warehouse_id]
        );
      }

      // Update Status Transaksi Pembelian menjadi Approved
      await trx.run(
        'UPDATE purchases SET status = "APPROVED", approved_at = ? WHERE id = ?',
        [new Date().toISOString(), purchaseId]
      );
    });

    return res.json({
      success: true,
      message: 'Faktur berhasil disahkan! Stok masuk telah dicatat secara otomatis.'
    });

  } catch (error) {
    console.error('Approval Error:', error);
    return res.status(500).json({ success: false, message: error.message });
  }
}

